INSERT INTO `modules` VALUES (3,'Starter Mission: Fundamental of Programming','Understanding the basics','basic','Gradually introduce stick control, telemetry variables and core safety logic before autonomous routines','../Assets/uploads/module-covers/cover-307bce4b9a808736.png','',NULL,0,0,'2026-01-01 17:21:21'),(6,'Drone Block Builder','Visual logic','block','Create your own drone missions with easy drag-and-drop blocks.','../Assets/uploads/module-covers/cover-afd6faa06189660d.png','',NULL,0,0,'2026-01-05 15:15:27'),(8,'Advanced Drone Development','ESP32 flight lab','advanced','Theme: \"Build and Code Your Own Drone\". Goal: guide cadets through real ESP32 hardware programming, basic flight control, and autonomous decision logic','../Assets/uploads/module-covers/cover-a763978db8c85288.png','',NULL,0,0,'2026-01-07 07:07:55');
/*!40000 ALTER TABLE `modules` ENABLE KEYS */;
DROP TABLE IF EXISTS `lessons`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `lessons` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `module_id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `focus` varchar(64) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `duration` varchar(64) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `video_url` varchar(512) DEFAULT NULL,
  `what_you_learn` text DEFAULT NULL,
  `learning_outcomes` text DEFAULT NULL,
  `quiz_questions` text DEFAULT NULL,
  `status` varchar(16) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`focus`),
  UNIQUE KEY `focus` (`focus`),
  KEY `module_id` (`module_id`),
  CONSTRAINT `fk_lessons_module` FOREIGN KEY (`module_id`) REFERENCES `modules` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=132 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

/*!40000 ALTER TABLE `lessons` DISABLE KEYS */;
INSERT INTO `lessons` VALUES (20,8,'Meet the ESP32','microcontroller-basics','Learn how the ESP32 microcontroller works, explore pins, power rails, and built-in Wi-Fi - Duration: 15 min','15 min','2026-01-07 07:10:59','','','','','open'),(21,8,'Setting Up Arduino IDE','toolchain-setup','Install the ESP32 board package, upload the Blink sketch, and verify the serial upload process. Video: ESP32 Blink Tutorial.','20 min','2026-01-07 07:10:59','','','','','open'),(22,8,'Reading Sensors','sensor-io','Wire an ultrasonic sensor, capture distance readings, and stream data into the Serial Monitor. Video: ESP32 Ultrasonic Sensor Tutorial.','25 min','2026-01-07 07:10:59','','','','','open'),(23,8,'Controlling Motors','motor-control','Drive a DC motor with PWM, script spin and stop routines, and monitor current draw. Video: ESP32 Motor Control.','30 min','2026-01-07 07:10:59','','','','','open'),(24,8,'Wireless Commands','networking','Bring the ESP32 onto Wi-Fi, host a simple web button, and send a take-off command remotely. Video: ESP32 Web Server Control.','25 min','2026-01-07 07:10:59','','','','','open'),(25,8,'Combine Sensors + Motors','control-logic','Blend ultrasonic data with motor PWM to stop propulsion whenever distance falls below 50 cm. Video: ESP32 Obstacle Avoidance Demo.','35 min','2026-01-07 07:10:59','','','','','open'),(26,6,'Takeoff & Landing Safety','takeoff','Power-up checks, safe takeoff and landing blocks, and the green-flag event to wrap it together. - Duration: 3 min','3 min','2026-01-07 07:16:43','','','','','locked'),(27,6,'Navigation: Move & Turn','navigation','Forward, back, left, right, and turn blocks with distance/degree inputs and simple safety spacing.','18 min','2026-01-07 07:16:43','','','','','open'),(28,6,'Camera: Shots & Framing','camera','Use camera/take-photo blocks, align shots with yaw moves, and add pauses for clearer captures.','15 min','2026-01-07 07:16:43','','','','','open'),(29,6,'Flip & Trick Basics','flip','Trigger flips safely, set heights, and chain simple trick combos with waits.','16 min','2026-01-07 07:16:43','','','','','open'),(30,6,'Loops for Patterns','loops','Repeat paths for grids and orbits; tune counts and delays for smooth patterns.','18 min','2026-01-07 07:16:43','','','','','open'),(31,6,'Logic: If/Else Rules','logic','Use logic blocks to guard moves—battery checks, height limits, and obstacle flags.','18 min','2026-01-07 07:16:43','','','','','open'),(32,6,'Math for Missions','math','Scale distances, clamp speeds, and combine operators to calculate safe paths.','17 min','2026-01-07 07:16:43','','','','','open'),(33,6,'Variables & Memory','18-min','Store reusable values like cruise speed, photo count, and altitudes; reuse across moves.','18 min','2026-01-07 07:16:43','','','','','open'),(34,6,'Capstone: Full Mission','capstone','Combine takeoff, navigation, camera, flips, loops, logic, math, and variables into one mission.','22 min','2026-01-07 07:16:43','','','','','open'),(126,3,'What is Programming?','foundation','Animations explain that programming is simply giving clear instructions to computers, just like we guide friends.','2 min','2026-01-07 09:24:28','https://youtu.be/KJXd73u1g2c','Learn how programmers break down problems, why computers need exact steps, and how code lives everywhere from microwaves to movie apps.','Explain programming as giving exact instructions,\nName the inputs, logic, and outputs in a simple program,','[{\"question\":\"What is programming?\",\"choices\":[\"Playing games on a computer\",\"Giving instructions to a computer to perform tasks\",\"Fixing computer hardware\",\"Drawing pictures on a computer\"],\"correct_index\":1},{\"question\":\"Which of the following best describes a program?\",\"choices\":[\"A type of computer\",\"A set of instructions for a computer\",\"A computer screen\",\"An internet connection\"],\"correct_index\":1},{\"question\":\"Who creates programs for computers?\",\"choices\":[\"Computer\",\"Teacher\",\"Programmer\",\"Internet\"],\"correct_index\":2},{\"question\":\"Which device needs programming to work correctly?\",\"choices\":[\"Chair\",\"Book\",\"Smartphone\",\"Pencil\"],\"correct_index\":2},{\"question\":\"Programming is mainly used to make computers:\",\"choices\":[\"Think like humans\",\"Follow instructions correctly\",\"Sleep when not used\",\"Work without electricity\"],\"correct_index\":1},{\"question\":\"Which example shows programming in daily life?\",\"choices\":[\"Writing a story\",\"Following a recipe step by step\",\"Reading a book\",\"Watching television\"],\"correct_index\":1},{\"question\":\"What happens if instructions in a program are unclear?\",\"choices\":[\"The computer will guess\",\"The computer will ignore them\",\"The computer may not work as expected\",\"The computer will fix it automatically\"],\"correct_index\":2},{\"question\":\"Programming languages are used to:\",\"choices\":[\"Talk to humans\",\"Communicate with computers\",\"Draw pictures only\",\"Control electricity\"],\"correct_index\":1},{\"question\":\"Which of the following is NOT a purpose of programming?\",\"choices\":[\"Creating games\",\"Controlling robots or drones\",\"Solving problems\",\"Making computers heavier\"],\"correct_index\":3},{\"question\":\"Programming teaches students to:\",\"choices\":[\"Memorize only\",\"Think logically and solve problems\",\"Type faster\",\"Use social media\"],\"correct_index\":1}]','open'),(127,3,'Humans vs Computers','computer-thinking','Compare how people improvise while computers only follow exact steps. Discover why order matters.','3 min','2026-01-07 09:24:28','5tZyH2nCvzw?rel=0','Explore why computers need every detail spelled out and practice rewriting casual directions so a','Translate messy language into precise commands\nDescribe why computers need exact, step-by-step detail','[{\"question\": \"What is the main difference between how humans and computers follow instructions?\", \"choices\": [\"Computers make up their own steps when some are missing\", \"Humans can fill in missing details, but computers follow only the exact steps given\", \"Computers understand how we feel\", \"Humans and computers follow instructions in exactly the same way\"], \"correct_index\": 1}, {\"question\": \"You tell a computer \\\"make a sandwich\\\" without giving any steps. What happens?\", \"choices\": [\"It makes your favourite sandwich\", \"It asks a friend for help\", \"It cannot do it because the steps were not given\", \"It guesses the best way to do it\"], \"correct_index\": 2}, {\"question\": \"Why does the order of instructions matter to a computer?\", \"choices\": [\"It runs the steps in exactly the order they are written\", \"It skips the steps it does not like\", \"It always starts from the last step\", \"The order does not matter to a computer\"], \"correct_index\": 0}, {\"question\": \"Which instruction is precise enough for a computer?\", \"choices\": [\"Move forward 3 steps\", \"Walk a bit forward\", \"Go over there\", \"Move until it feels right\"], \"correct_index\": 0}, {\"question\": \"The instructions say \\\"Put on your shoes, then your socks\\\". What would a computer do?\", \"choices\": [\"Fix the order by itself\", \"Put on the shoes first, then the socks, exactly as written\", \"Ask what you really meant\", \"Skip both steps\"], \"correct_index\": 1}, {\"question\": \"Which of these can a human do that a computer cannot do on its own?\", \"choices\": [\"Repeat a task many times\", \"Calculate very quickly\", \"Use common sense to fill in missing steps\", \"Store a lot of information\"], \"correct_index\": 2}, {\"question\": \"Which of these is a strength of computers?\", \"choices\": [\"Guessing what you meant\", \"Understanding jokes\", \"Changing the plan when they feel like it\", \"Following the same steps quickly without getting tired\"], \"correct_index\": 3}, {\"question\": \"Which is the best way to rewrite \\\"Clean your room\\\" as a precise command?\", \"choices\": [\"Make it look nice\", \"Tidy up a little\", \"Pick up the 5 books from the floor and put them on the shelf\", \"Clean as much as you want\"], \"correct_index\": 2}, {\"question\": \"What is a \\\"bug\\\" in a program?\", \"choices\": [\"A mistake in the instructions that makes the program go wrong\", \"A small insect inside the computer\", \"A new computer game\", \"A faster way to run a program\"], \"correct_index\": 0}, {\"question\": \"Why do programmers need to write every detail for a computer?\", \"choices\": [\"Computers like long instructions\", \"It makes the computer run slower\", \"Computers get angry with short instructions\", \"Computers do exactly what they are told and cannot guess the missing parts\"], \"correct_index\": 3}]','open'),(128,3,'Everyday Instructions','algorithms','Turn brushing teeth or making toast into an algorithm to see how daily routines become programs.','1 min','2026-01-07 09:24:28','https://youtu.be/r_Rsu6Av1Vk','Learn to break daily routines into numbered steps so someone else - or a computer - can repeat them without confusion.','Break everyday tasks into ordered instructions\nSpot the decision points hiding in chores\nShare steps that another person can follow without guessing.','[{\"question\": \"What is an algorithm?\", \"choices\": [\"A brand of computer\", \"A list of steps to solve a problem or finish a task\", \"A type of video game\", \"The answer to a math question\"], \"correct_index\": 1}, {\"question\": \"What is the first step of brushing your teeth?\", \"choices\": [\"Pick up your toothbrush\", \"Rinse your mouth\", \"Brush your back teeth\", \"Put the toothbrush away\"], \"correct_index\": 0}, {\"question\": \"Why do we number the steps of an algorithm?\", \"choices\": [\"To make it look longer\", \"Because computers only understand numbers\", \"So the steps are followed in the right order\", \"So we can skip steps easily\"], \"correct_index\": 2}, {\"question\": \"Making toast: which step comes right after putting the bread in the toaster?\", \"choices\": [\"Eat the toast\", \"Take the bread out of the bag\", \"Spread butter on the toast\", \"Press the lever to start toasting\"], \"correct_index\": 3}, {\"question\": \"What is a decision point in an algorithm?\", \"choices\": [\"A step where you choose what to do based on a question, like \\\"Is the water hot?\\\"\", \"The last step of the algorithm\", \"A step that repeats forever\", \"A step with no instruction\"], \"correct_index\": 0}, {\"question\": \"Which of these is a decision point in a morning routine?\", \"choices\": [\"Put on your shirt\", \"Is it raining? If yes, take an umbrella\", \"Eat breakfast\", \"Brush your hair\"], \"correct_index\": 1}, {\"question\": \"What can happen if a step is missing from an algorithm?\", \"choices\": [\"The task may not be finished correctly\", \"Nothing changes\", \"The task becomes faster and better\", \"The computer adds the missing step by itself\"], \"correct_index\": 0}, {\"question\": \"Which everyday activity is an example of an algorithm?\", \"choices\": [\"Daydreaming\", \"Sleeping\", \"Following the steps of a recipe\", \"Feeling happy\"], \"correct_index\": 2}, {\"question\": \"A good algorithm should be:\", \"choices\": [\"Long and confusing\", \"Clear, in order, and easy for someone else to follow\", \"Written only with pictures\", \"Different every time it is used\"], \"correct_index\": 1}, {\"question\": \"You give a friend steps to draw a house, but they draw the roof under the walls. What is the most likely problem?\", \"choices\": [\"The pencil was broken\", \"The paper was too small\", \"Houses cannot be drawn with steps\", \"The steps were unclear or in the wrong order\"], \"correct_index\": 3}]','open'),(129,3,'Algorithms & Flowcharts','flowcharts','Sketch simple flowcharts using start/end, arrows, and decision diamonds to map a recipe.','10 min','2026-01-07 09:24:28','https://youtu.be/RwnY_mJ6ras','Learn the start/end, process, and decision symbols that map any algorithm into a visual plan.','Recognize core flowchart shapes and their meaning\nTranslate a written algorithm into a diagram','[{\"question\": \"What is a flowchart?\", \"choices\": [\"A chart that shows the weather\", \"A list of computer parts\", \"A diagram that shows the steps of an algorithm using shapes and arrows\", \"A drawing of a river\"], \"correct_index\": 2}, {\"question\": \"Which shape is used for Start and End in a flowchart?\", \"choices\": [\"Oval\", \"Diamond\", \"Rectangle\", \"Triangle\"], \"correct_index\": 0}, {\"question\": \"Which shape shows a process step, like \\\"Mix the flour\\\"?\", \"choices\": [\"Oval\", \"Rectangle\", \"Diamond\", \"Star\"], \"correct_index\": 1}, {\"question\": \"Which shape is used for a decision, like \\\"Is the cake ready?\\\"\", \"choices\": [\"Rectangle\", \"Oval\", \"Circle\", \"Diamond\"], \"correct_index\": 3}, {\"question\": \"What do the arrows in a flowchart show?\", \"choices\": [\"The order in which the steps are followed\", \"The size of each step\", \"Which step is the most important\", \"Where to stop drawing\"], \"correct_index\": 0}, {\"question\": \"How many paths usually come out of a decision diamond?\", \"choices\": [\"One\", \"Two, such as Yes and No\", \"None\", \"Five\"], \"correct_index\": 1}, {\"question\": \"Where does every flowchart begin?\", \"choices\": [\"At the Start oval\", \"At the first diamond\", \"At the End oval\", \"Anywhere on the page\"], \"correct_index\": 0}, {\"question\": \"In a flowchart, the decision \\\"Is the water boiling?\\\" is answered No. What usually happens next?\", \"choices\": [\"The flowchart ends\", \"You skip straight to drinking\", \"An arrow goes back so you wait and check again\", \"You start a different recipe\"], \"correct_index\": 2}, {\"question\": \"Why do programmers draw flowcharts before writing code?\", \"choices\": [\"Because code needs colours\", \"To make the program run faster\", \"To replace the code completely\", \"To plan the steps and spot mistakes early\"], \"correct_index\": 3}, {\"question\": \"Which flowchart is in the correct order?\", \"choices\": [\"Start → Pour into cup → Boil water → End\", \"Start → Boil water → Is the water boiling? → Pour into cup → End\", \"End → Boil water → Start\", \"Is the water boiling? → Start → End\"], \"correct_index\": 1}]','open'),(130,3,'Variables Explained Simply','variables','See how boxes can store numbers, text, or states and why changing them changes your program.','5 min','2026-01-07 09:24:28','','See how variables capture info, how values change, and why constants and variables work together','Explain variables as containers that can change\nTell the difference between constants and variables.','[{\"question\": \"What is a variable in programming?\", \"choices\": [\"A container that stores a value that can change\", \"A broken computer\", \"A type of keyboard\", \"A number that can never change\"], \"correct_index\": 0}, {\"question\": \"What can a variable store?\", \"choices\": [\"Only numbers\", \"Only pictures\", \"Numbers, text, or true/false values\", \"Nothing at all\"], \"correct_index\": 2}, {\"question\": \"In a game, the score starts at 0 and becomes 10 after you collect a coin. What is the score?\", \"choices\": [\"A constant\", \"A variable\", \"A flowchart\", \"A bug\"], \"correct_index\": 1}, {\"question\": \"What is a constant?\", \"choices\": [\"A value that changes all the time\", \"A value that stays the same while the program runs\", \"A type of loop\", \"A decision point\"], \"correct_index\": 1}, {\"question\": \"Which of these is best kept as a constant?\", \"choices\": [\"A player\'s score\", \"The time left in a game\", \"A drone\'s battery level\", \"The number of days in a week\"], \"correct_index\": 3}, {\"question\": \"Why do we give variables names like speed or playerName?\", \"choices\": [\"So we can find and use the stored value later\", \"To make the program colourful\", \"Because computers need long words\", \"Names are not needed for variables\"], \"correct_index\": 0}, {\"question\": \"A program sets speed = 5, then later sets speed = 8. What is the value of speed now?\", \"choices\": [\"5\", \"13\", \"8\", \"0\"], \"correct_index\": 2}, {\"question\": \"Which variable name is the clearest?\", \"choices\": [\"x1\", \"batteryLevel\", \"thing\", \"aaa\"], \"correct_index\": 1}, {\"question\": \"A drone program stores its height in a variable. What happens to the variable when the drone climbs higher?\", \"choices\": [\"It stays the same\", \"It is deleted\", \"It becomes a constant\", \"Its value changes to the new height\"], \"correct_index\": 3}, {\"question\": \"Which of these stores a true/false value?\", \"choices\": [\"name = \\\"Ali\\\"\", \"age = 25\", \"isFlying = true\", \"pi = 3.14\"], \"correct_index\": 2}]','open');
